import base64
from contextlib import suppress
from hashlib import sha256
import http.client as http_client
import json
import os
from pathlib import Path
import re
import select
import signal
import stat
import subprocess
import sys
import tempfile
import time
from types import ModuleType
from urllib.parse import urlsplit


BUNDLE = {"owner_quick_tunnel_launch.py":"","owner_quick_chat_install.py":"","owner_refresh_cognition_c04.py":"","attach_resonance_turn_resume.py":"","owner_resonance_turn_fidelity.py":""}
LAUNCH = 'owner_quick_tunnel_launch.py'
INSTALL = 'owner_quick_chat_install.py'
NATIVE = 'owner_refresh_cognition_c04.py'
GATEWAY = 'owner_resonance_gateway.py'
OLD_SHA = '4dfc48d178de35c1ba3b6625fd2cd7e2df891b3dac6c515947971e4863a97eeb'
NEW_SHA = 'bcdcb1244605c7ea6555322f02f9db39dd1a2e067c5841e8bc128e34e16b9fe6'
PINS = {'owner_quick_tunnel_launch.py': 'e5e0e29bd26e3f1acb55d59212e8188e15c2fc01af51597006226d080f1826c6', 'owner_quick_chat_install.py': 'e52ab87b4b0c1fa8f00bb8ef5c40f92abf523df3bebf04d87dcbbb2475f46ee8', 'owner_refresh_cognition_c04.py': 'fdd6e646c8cef1fad9a6d39afa2723375fa2e6126bf4da4989b751ffc2355de0', 'attach_resonance_turn_resume.py': 'b7b06357446f0ce673c1b1d8abd1d2caa304deb7ce4d78dac14ed00c079a6b9a', 'owner_resonance_turn_fidelity.py': 'fc89a261ab91d77f3a1f673686b2240e6b109b2081054b2a672acb5e8744e112'}
PYTHON = '/usr/bin/python3'
TIMEOUT = ('/usr/bin/timeout', '--foreground', '--signal=TERM', '--kill-after=5s')
TCP = Path('/proc/net/tcp')
TURN = '/api/nox/chat/turn'
WOW_MENU = b'/nox-web-v29/wow/pc/menu.html'
VERIFY_ONLY = False
STAGE = 'bootstrap'


def need(value, code):
    if not value:
        raise RuntimeError('HOLD_WEB_EDGE_' + code)


def digest(raw):
    return sha256(raw).hexdigest()


def load():
    need(set(BUNDLE) == set(PINS), 'BUNDLE_SCOPE')
    raw = {}
    for name, pin in PINS.items():
        value = BUNDLE[name]
        need(isinstance(value, str) and len(value) <= 70000, 'BUNDLE_SIZE')
        raw[name] = base64.b64decode(value, validate=True)
        need(digest(raw[name]) == pin, 'BUNDLE_PIN')
    modules = []
    for name in (LAUNCH, INSTALL, NATIVE, 'attach_resonance_turn_resume.py', 'owner_resonance_turn_fidelity.py'):
        module = ModuleType(Path(name).stem)
        sys.modules[module.__name__] = module
        exec(compile(raw[name], name, 'exec'), module.__dict__)
        modules.append(module)
    return modules


def page_bytes(candidate):
    import ast
    tree = ast.parse(candidate)
    pages = [node.value for node in tree.body if isinstance(node, ast.Assign)
             and any(isinstance(item, ast.Name) and item.id == 'PAGE' for item in node.targets)]
    need(len(pages) == 1, 'CANDIDATE_PAGE')
    attribute = pages[0].func if isinstance(pages[0], ast.Call) else None
    need(isinstance(attribute, ast.Attribute) and attribute.attr == 'encode'
         and isinstance(attribute.value, ast.Constant) and isinstance(attribute.value.value, str)
         and not pages[0].args and not pages[0].keywords, 'CANDIDATE_PAGE')
    result = attribute.value.value.encode()
    need(TURN.encode() in result and WOW_MENU in result, 'CANDIDATE_PAGE')
    return result


def trusted_read(launch, path, limit, mode):
    with os.fdopen(launch.read_fd(path, limit), 'rb') as stream:
        opened = os.fstat(stream.fileno())
        data = stream.read(limit + 1)
    current = path.lstat()
    need(len(data) == opened.st_size <= limit and stat.S_IMODE(opened.st_mode) == mode
         and os.path.samestat(opened, current) and opened.st_mtime_ns == current.st_mtime_ns,
         'SOURCE_CHANGED')
    return data


def write_atomic(launch, path, data, preimage, limit, *, create=False):
    fd, temporary = tempfile.mkstemp(prefix='.web-edge-', dir=launch.WORK)
    try:
        with os.fdopen(fd, 'wb') as stream:
            need(stream.write(data) == len(data), 'SOURCE_WRITE')
            os.fchmod(stream.fileno(), 0o400)
            stream.flush()
            os.fsync(stream.fileno())
        if create:
            try:
                os.link(temporary, path)
            except FileExistsError:
                pass
        else:
            need(digest(trusted_read(launch, path, limit, 0o400)) == preimage, 'SOURCE_CAS')
            os.replace(temporary, path)
        with suppress(FileNotFoundError):
            os.unlink(temporary)
        launch.sync_dir(launch.WORK)
        need(trusted_read(launch, path, limit, 0o400) == data, 'SOURCE_READBACK')
    finally:
        with suppress(FileNotFoundError):
            os.unlink(temporary)


def assert_command(launch, pid, ticks, command, binary):
    directory = Path('/proc') / str(pid)
    with (directory / 'cmdline').open('rb') as stream:
        argv = stream.read(4097)
    need(directory.stat().st_uid == directory.stat().st_gid == 0
         and launch.start_ticks(pid) == ticks
         and argv == b'\0'.join(map(os.fsencode, (*command, '')))
         and os.path.samestat((directory / 'exe').stat(), Path(binary).stat()), 'PROCESS_IDENTITY')


def listener_inode(launch, *, idle):
    with TCP.open() as stream:
        raw = stream.read(2_000_001)
    need(len(raw) <= 2_000_000, 'TCP_BOUNDS')
    address = '0100007F:' + format(launch.GATEWAY, '04X')
    rows = [fields for line in raw.splitlines()[1:] if len(fields := line.split()) > 9
            and fields[1] == address]
    sockets = [row[9] for row in rows if row[3] == '0A']
    need(len(sockets) == 1 and (not idle or all(row[3] not in ('01', '03', '08') for row in rows)),
         'EDGE_BUSY_OR_LISTENER')
    return 'socket:[' + sockets[0] + ']'


def has_listener(pid, expected):
    for index, fd in enumerate((Path('/proc') / str(pid) / 'fd').iterdir()):
        need(index < 256, 'PROCESS_FD_BOUNDS')
        with suppress(FileNotFoundError):
            if fd.readlink().name == expected:
                return True
    return False


def listener(launch, pid, *, idle):
    need(has_listener(pid, listener_inode(launch, idle=idle)), 'LISTENER_OWNER')


def command_bytes(command):
    return b'\0'.join(map(os.fsencode, (*command, '')))


def gateway_identity(launch, install, path):
    """Pin the actual edge child, its timeout parent and the live listener."""
    python = (PYTHON, '-I', '-B', str(path))
    python_argv = command_bytes(python)
    sock = listener_inode(launch, idle=False)
    candidates = []
    with os.scandir('/proc') as processes:
        for index, item in enumerate(processes):
            need(index < 8192, 'PROCESS_SCAN_BOUND')
            if not item.name.isdecimal():
                continue
            process = Path(item.path)
            try:
                with (process / 'cmdline').open('rb') as stream:
                    if stream.read(4097) != python_argv:
                        continue
                pid = int(item.name)
                if has_listener(pid, sock):
                    candidates.append((pid, process))
            except (FileNotFoundError, ProcessLookupError):
                continue
    need(len(candidates) == 1, 'GATEWAY_CHILD_SCOPE')
    child, process = candidates[0]
    with (process / 'stat').open('rb') as stream:
        fields = stream.read(4097).rpartition(b') ')[2].split()
    need(len(fields) > 19 and fields[1].isdigit() and fields[19].isdigit(), 'GATEWAY_CHILD_STAT')
    parent, ticks = int(fields[1]), int(fields[19])
    need(parent > 1 and ticks > 0, 'GATEWAY_CHILD_STAT')
    parent_path = Path('/proc') / str(parent)
    with (parent_path / 'cmdline').open('rb') as stream:
        fields = stream.read(4097).split(b'\0')
    need(len(fields) == len(TIMEOUT) + len(python) + 2
         and re.fullmatch(rb'[1-9][0-9]{0,5}', fields[len(TIMEOUT)]), 'GATEWAY_PARENT_COMMAND')
    budget = int(fields[len(TIMEOUT)])
    need(budget <= launch.TTL_SECONDS + 180, 'GATEWAY_PARENT_DURATION')
    parent_ticks = launch.start_ticks(parent)
    assert_command(launch, parent, parent_ticks, (*TIMEOUT, str(budget), *python), TIMEOUT[0])
    assert_command(launch, child, ticks, python, PYTHON)
    need(install.gateway_process(parent) == (child, ticks), 'ORIGINAL_PARENT')
    return (child, ticks), (parent, parent_ticks), sock


def metrics_request(launch, path):
    connection = http_client.HTTPConnection(launch.LOCAL, launch.METRICS, timeout=3)
    try:
        connection.request('GET', path, headers={'Connection':'close'})
        response = connection.getresponse()
        data = response.read(4097)
        need(response.status == 200 and len(data) <= 4096, 'TUNNEL_METRICS')
        return data
    finally:
        connection.close()


def tunnel_ok(launch, record, *, verify_binary=True):
    """Validate the current owner receipt against the running tunnel."""
    need(isinstance(record, dict) and record.get('schema') == 'NOX_QUICK_CHAT_TUNNEL_V1'
         and record.get('temporary') is True, 'TUNNEL_SCHEMA')
    need(record.get('gateway_sha256') == OLD_SHA, 'TUNNEL_GATEWAY_PIN')
    need(record.get('cloudflared_sha256') == launch.PIN, 'TUNNEL_BINARY_PIN')
    parents = ('ttl_pid','ttl_start_ticks','cloudflared_pid','cloudflared_start_ticks')
    need(all(type(record.get(key)) is int and record[key] > 1 for key in parents), 'TUNNEL_PROCESS_FIELDS')
    expires = record.get('expires_unix')
    need(type(expires) is int and 90 <= expires - time.time() <= launch.TTL_SECONDS, 'TUNNEL_EXPIRY')
    endpoint = record.get('url')
    need(isinstance(endpoint, str) and re.fullmatch(r'https://[^/]+/chat', endpoint), 'TUNNEL_URL')
    hostname = urlsplit(endpoint).hostname
    need(hostname is not None and launch.DOMAIN.fullmatch(hostname)
         and endpoint == 'https://' + hostname + '/chat', 'TUNNEL_URL')
    parent, ticks, child, child_ticks = (record[key] for key in parents)
    parent_command = (*TIMEOUT, str(launch.TTL_SECONDS), str(launch.BINARY), 'tunnel', '--no-autoupdate',
                      '--loglevel', 'warn', '--metrics', f'{launch.LOCAL}:{launch.METRICS}',
                      '--url', f'http://{launch.LOCAL}:{launch.GATEWAY}')
    assert_command(launch, parent, ticks, parent_command, TIMEOUT[0])
    need(launch.owned_cloudflared(parent, launch.BINARY) == (child, child_ticks), 'TUNNEL_IDENTITY')
    if verify_binary:
        with os.fdopen(launch.read_fd(launch.BINARY, launch.MAX_BINARY, executable=True), 'rb') as binary:
            need(launch.copy_pinned(binary, None), 'TUNNEL_BINARY_DISK')
    expected_expiry = time.time() + launch.TTL_SECONDS - (
        time.clock_gettime(time.CLOCK_BOOTTIME) - ticks / os.sysconf('SC_CLK_TCK'))
    need(abs(expected_expiry - expires) <= 10, 'TUNNEL_EXPIRY_PROCESS')
    metrics = json.loads(metrics_request(launch, '/quicktunnel'))
    metric_host = metrics.get('hostname') if isinstance(metrics, dict) else None
    need(isinstance(metric_host, str) and metric_host.removeprefix('https://') == hostname,
         'TUNNEL_ROUTE_CAS')
    metrics_request(launch, '/ready')
    return endpoint, expires, (child, child_ticks)


def http(launch, host, path, *, external=False, json_body=None):
    connection = (http_client.HTTPSConnection(host, 443, timeout=8) if external else
                  http_client.HTTPConnection(launch.LOCAL, launch.GATEWAY, timeout=4))
    headers = {'Host': host, 'Connection': 'close', 'Accept-Encoding': 'identity'}
    try:
        if json_body is None:
            connection.request('GET', path, headers=headers)
        else:
            headers.update({'Origin': 'https://' + host, 'Content-Type': 'application/json'})
            connection.request('POST', path, body=json_body, headers=headers)
        response = connection.getresponse()
        raw = response.read(49153)
        need(len(raw) <= 49152, 'HTTP_SIZE')
        return response.status, raw
    finally:
        connection.close()


def readback(launch, host, expected, *, upgraded):
    for external in (False, True):
        need(http(launch, host, '/chat', external=external) == (200, expected)
             and http(launch, host, '/chat/session', external=external)[0] == 401, 'CHAT_READBACK')
    if upgraded:
        binding = {'dialog_id': 'a' * 32, 'request_id': 'b' * 32}
        query = '?dialog_id=' + binding['dialog_id'] + '&request_id=' + binding['request_id'] + '&after=0'
        need(http(launch, host, TURN + query)[0] == 401
             and http(launch, host, TURN + '/stop', json_body=json.dumps(binding).encode())[0] == 401
             and http(launch, host, '/api/nox/stop', json_body=b'{}')[0] == 404, 'WEB_ACCESS_GUARDS')


def old_health(launch, host):
    status, raw = http(launch, host, '/_nox_edge_health')
    need(status == 200 and 0 < len(raw) <= 4096, 'ORIGINAL_HEALTH_STATUS')
    try:
        health = json.loads(raw)
    except (ValueError, RecursionError):
        raise RuntimeError('HOLD_WEB_EDGE_ORIGINAL_HEALTH_JSON') from None
    need(isinstance(health, dict) and health.get('service') == 'nox-quick-chat-gateway'
         and health.get('ready') is True and health.get('source_sha256') == OLD_SHA, 'ORIGINAL_HEALTH_PIN')


def start(launch, install, path, pin, lease, expires):
    ttl = max(1, int(expires - time.time()) + 180)
    args = (*TIMEOUT, str(ttl), PYTHON, '-I', '-B', str(path))
    fd, logfile = tempfile.mkstemp(prefix='gateway-web-', suffix='.log', dir=launch.WORK)
    with os.fdopen(fd, 'wb') as stream:
        lease()
        process = subprocess.Popen(args, stdin=subprocess.DEVNULL, stdout=stream,
                                   stderr=subprocess.STDOUT, start_new_session=True,
                                   close_fds=True, cwd=launch.WORK, preexec_fn=launch.child_limits,
                                   env={'PATH':'/usr/bin:/bin','HOME':str(launch.WORK),'LC_ALL':'C'})
    try:
        pid, ticks = install.wait_gateway(process, pin)
        listener(launch, pid, idle=False)
        identity = {'gateway_pid': pid, 'gateway_start_ticks': ticks,
                    'gateway_ttl_pid': process.pid, 'gateway_ttl_start_ticks': launch.start_ticks(process.pid),
                    'gateway_log_name': Path(logfile).name}
        return process, identity
    except BaseException:
        install.stop_started(process)
        raise


def threads_stopped(pid):
    tasks = Path('/proc') / str(pid) / 'task'
    children = list(tasks.iterdir())
    if len(children) != 1 or children[0].name != str(pid):
        return False
    with (children[0] / 'status').open() as stream:
        for line in stream:
            if line.startswith('State:'):
                return line.split()[1] == 'T'
    return False


def exited(pidfd, seconds):
    poller = select.poll()
    poller.register(pidfd, select.POLLIN)
    return bool(poller.poll(seconds * 1000))


def main():
    global STAGE
    STAGE = 'owner_context'
    owner = os.environ.get('NOX_OWNER_REQUEST_ID', '')
    source = os.environ.get('NOX_OWNER_SOURCE_SHA', '')
    labels = {os.environ[k].removeprefix('C.') for k in ('VAST_CONTAINERLABEL','CONTAINER_ID') if os.environ.get(k)}
    need(os.geteuid() == os.getegid() == 0 and labels == {'60509551'}
         and re.fullmatch('[1-9][0-9]{0,19}', owner) and re.fullmatch('[a-f0-9]{40}', source),
         'OWNER_CONTEXT')
    STAGE = 'bundle'
    launch, install, native, resume, fidelity = load()
    path = install.DESTINATION
    backup = path.with_name('owner_resonance_gateway.pre-wow-resume.py')
    STAGE = 'lease'
    with launch.maintenance_lease() as lease:
        launch.path_trusted(launch.WORK)
        need(stat.S_IMODE(launch.WORK.lstat().st_mode) == 0o700, 'WORK_MODE')
        STAGE = 'tunnel_receipt'
        active = trusted_read(launch, launch.RECEIPT, 4096, 0o600)
        record = json.loads(active)
        tunnel = tunnel_ok(launch, record)
        url, expires, cloudflared = tunnel
        host = urlsplit(url).hostname
        need(host is not None and launch.DOMAIN.fullmatch(host), 'HTTPS_HOST')
        STAGE = 'original_source'
        before = trusted_read(launch, path, install.MAX_GATEWAY, 0o400)
        need(digest(before) == OLD_SHA, 'ORIGINAL_SOURCE_PIN')
        old_page = page_bytes(before)
        STAGE = 'original_page'
        readback(launch, host, old_page, upgraded=True)
        old_health(launch, host)
        STAGE = 'build_candidate'
        intermediate = resume.attach_turn_resume(before)
        need(digest(intermediate) == '457691320034464267f5c772ce01b4c69682ce3740b2f5ed91553a5a52c07e53',
             'BROWSER_POSTIMAGE')
        candidate = fidelity.transform_turn_fidelity(intermediate, reviewed_sha256=digest(intermediate))
        need(digest(candidate) == NEW_SHA and len(candidate) <= install.MAX_GATEWAY, 'COMBINED_POSTIMAGE')
        expected_page = page_bytes(candidate)

        STAGE = 'original_processes'
        (old_pid, old_ticks), (parent_pid, parent_ticks), socket_id = gateway_identity(launch, install, path)
        old_child = (old_pid, old_ticks)
        python_command = (PYTHON, '-I', '-B', str(path))
        lease()
        need(trusted_read(launch, launch.RECEIPT, 4096, 0o600) == active, 'RECEIPT_CAS')
        preimage = {'gateway_pid': old_pid, 'gateway_start_ticks': old_ticks, 'source_sha256': OLD_SHA,
                    'gateway_ttl_pid': parent_pid, 'gateway_ttl_start_ticks': parent_ticks,
                    'cloudflared_pid': cloudflared[0], 'cloudflared_start_ticks': cloudflared[1],
                    'expires_unix': expires, 'prior_https_chat_ready': True}
        print('NOX_MAINT_WEB_EDGE_PREIMAGE=' + json.dumps(preimage, sort_keys=True, separators=(',',':')), flush=True)
        if VERIFY_ONLY:
            print('NOX_MAINT_REPAIR_COMPLETE=true', flush=True)
            return

        STAGE = 'process_api'
        need(callable(getattr(os, 'pidfd_open', None)) and callable(getattr(signal, 'pidfd_send_signal', None)),
             'PIDFD_UNAVAILABLE')
        STAGE = 'backup'
        STAGE = 'native_idle'
        native.idle()
        native.stop_clear()
        STAGE = 'backup'
        write_atomic(launch, backup, before, None, install.MAX_GATEWAY, create=True)
        lease()
        need(trusted_read(launch, launch.RECEIPT, 4096, 0o600) == active, 'RECEIPT_CAS')
        need(tunnel_ok(launch, record, verify_binary=False) == tunnel, 'TUNNEL_CAS')
        STAGE = 'pidfds'
        with os.fdopen(os.pidfd_open(old_pid), 'rb') as old, os.fdopen(os.pidfd_open(parent_pid), 'rb') as parent:
            frozen = stopped = False
            new_process = None
            try:
                assert_command(launch, old_pid, old_ticks, python_command, PYTHON)
                need(launch.start_ticks(parent_pid) == parent_ticks and install.gateway_process(parent_pid) == old_child, 'ORIGINAL_PARENT')
                STAGE = 'freeze'
                signal.pidfd_send_signal(old.fileno(), signal.SIGSTOP)
                frozen = True
                deadline = time.monotonic() + 0.5
                while not threads_stopped(old_pid) and time.monotonic() < deadline:
                    time.sleep(0.025)
                need(threads_stopped(old_pid), 'ORIGINAL_WORKERS_BUSY')
                need(listener_inode(launch, idle=True) == socket_id and has_listener(old_pid, socket_id),
                     'LISTENER_CAS')
                lease()
                STAGE = 'original_exit'
                signal.pidfd_send_signal(old.fileno(), signal.SIGKILL)
                stopped = True
                need(exited(old.fileno(), 5) and exited(parent.fileno(), 5), 'ORIGINAL_PROCESS_EXIT')
                STAGE = 'promote'
                write_atomic(launch, path, candidate, OLD_SHA, install.MAX_GATEWAY)
                STAGE = 'new_start'
                new_process, identity = start(launch, install, path, NEW_SHA, lease, expires)
                STAGE = 'new_readback'
                readback(launch, host, expected_page, upgraded=True)
                need(tunnel_ok(launch, record, verify_binary=False) == tunnel, 'TUNNEL_CAS')
                lease()
                need(trusted_read(launch, launch.RECEIPT, 4096, 0o600) == active, 'RECEIPT_CAS')
                updated = dict(record, **identity, gateway_sha256=NEW_SHA,
                               web_gateway_request=owner, web_gateway_source_sha=source)
                STAGE = 'new_receipt'
                launch.write_receipt(updated)
            except BaseException as original_error:
                if not stopped:
                    if frozen:
                        with suppress(ProcessLookupError):
                            signal.pidfd_send_signal(old.fileno(), signal.SIGCONT)
                    raise
                print('NOX_MAINT_WEB_EDGE_PRIMARY=' + diagnostics(original_error), flush=True)
                STAGE = 'rollback'
                if new_process is not None:
                    install.stop_started(new_process)
                need(exited(old.fileno(), 5) and exited(parent.fileno(), 5), 'ROLLBACK_PROCESS_SCOPE')
                current = trusted_read(launch, path, install.MAX_GATEWAY, 0o400)
                need(digest(current) in (NEW_SHA, OLD_SHA), 'ROLLBACK_SOURCE_SCOPE')
                if current != before:
                    write_atomic(launch, path, before, NEW_SHA, install.MAX_GATEWAY)
                _, identity = start(launch, install, path, OLD_SHA, lease, expires)
                launch.write_receipt(dict(record, **identity))
                readback(launch, host, old_page, upgraded=True)
                need(tunnel_ok(launch, record, verify_binary=False) == tunnel, 'ROLLBACK_TUNNEL')
                raise RuntimeError('HOLD_WEB_EDGE_ROLLBACK_ORIGINAL_READY') from None

    value = {'schema':'NOX_WEB_SAME_EDGE_ACTIVATION_V1', 'request':owner, 'source_sha':source,
             **identity, 'source_sha256':NEW_SHA, 'backup_sha256':OLD_SHA,
             'same_tunnel_process':True, 'same_https_chat_url':True, 'scope':'edge_only'}
    print('NOX_MAINT_WEB_EDGE=' + json.dumps(value, sort_keys=True, separators=(',',':')), flush=True)
    print('NOX_MAINT_REPAIR_COMPLETE=true', flush=True)


def diagnostics(error):
    trace = error.__traceback__
    while trace is not None and trace.tb_next is not None:
        trace = trace.tb_next
    function = trace.tb_frame.f_code.co_name if trace is not None else 'unknown'
    name = type(error).__name__
    safe = lambda value: value if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{0,63}', value) else 'unknown'
    return json.dumps({'stage': safe(STAGE), 'exception': safe(name), 'function': safe(function),
                       'line': trace.tb_lineno if trace is not None else 0}, separators=(',',':'))


if __name__ == '__main__':
    try:
        main()
    except Exception as exc:
        raw = str(exc)
        reason = raw if re.fullmatch(r'HOLD_[A-Z0-9_]{1,120}', raw) else 'HOLD_WEB_EDGE_' + type(exc).__name__.upper()
        print('NOX_MAINT_WEB_EDGE_DIAGNOSTIC=' + diagnostics(exc), flush=True)
        print('NOX_MAINT_WEB_EDGE_HOLD=' + reason, flush=True)
        raise SystemExit(2)
